fn reproducibility_certificate(policy:&str)->ReproducibilityCertificate{let certificate_id="repro-certificate-1".to_string();let authority_id="repro-authority-1".to_string();let bundle_sha256=hex('1');let fault_plan_sha256=hex('2');let trace_sha256=hex('3');let result_sha256=hex('4');let engine_ids=BTreeSet::from(["engine-1".to_string(),"engine-2".to_string()]);let receipt_sha256=BTreeSet::from([hex('5'),hex('6')]);let quorum=2;let authority_audit_tail_hash=hex('7');let certificate_sha256=hash_serializable(&(&certificate_id,&authority_id,policy,&bundle_sha256,&fault_plan_sha256,&trace_sha256,&result_sha256,&engine_ids,&receipt_sha256,quorum,&authority_audit_tail_hash)).unwrap();ReproducibilityCertificate{certificate_id,authority_id,policy_snapshot_sha256:policy.into(),bundle_sha256,fault_plan_sha256,trace_sha256,result_sha256,engine_ids,receipt_sha256,quorum,authority_audit_tail_hash,certificate_sha256}}
